"""Order and fill data structures for the backtesting engine."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from enum import Enum


class OrderSide(str, Enum):
    BUY = "buy"
    SELL = "sell"


class OrderType(str, Enum):
    MARKET = "market"
    LIMIT = "limit"
    STOP = "stop"


class OrderStatus(str, Enum):
    PENDING = "pending"
    FILLED = "filled"
    CANCELLED = "cancelled"
    REJECTED = "rejected"


@dataclass
class Order:
    """An order generated by the strategy or risk engine."""

    side: OrderSide
    quantity: float
    signal_bar_index: int
    reason: str = ""
    opens_position: bool = False
    # Pyramiding: adds to the open position instead of opening a new one.
    adds_to_position: bool = False
    stop_loss_price: float | None = None
    take_profit_price: float | None = None
    order_type: OrderType = OrderType.MARKET
    # Absolute trigger/limit price for LIMIT and STOP orders.
    limit_price: float | None = None
    status: OrderStatus = OrderStatus.PENDING
    created_at: datetime | None = None


@dataclass
class Fill:
    """An executed order fill."""

    order: Order
    fill_bar_index: int
    fill_date: datetime
    price: float
    quantity: float
    commission: float
    slippage_cost: float
    side: OrderSide

    @property
    def notional(self) -> float:
        return self.price * self.quantity


def resolve_pending_fill(
    order: Order,
    *,
    open_: float,
    high: float,
    low: float,
) -> float | None:
    """Return the raw fill price if ``order`` is triggered on this bar, else None.

    Convention (conservative, bar-based):
    - MARKET: next-open fill (caller passes the open as the candidate).
    - LIMIT buy: fill when low <= limit; price = min(open, limit).
    - LIMIT sell: fill when high >= limit; price = max(open, limit).
    - STOP buy: fill when high >= stop; price = max(open, stop).
    - STOP sell: fill when low <= stop; price = min(open, stop).
    """
    if order.order_type == OrderType.MARKET:
        return open_

    px = order.limit_price
    if px is None or px <= 0:
        return open_

    if order.order_type == OrderType.LIMIT:
        if order.side == OrderSide.BUY:
            if low <= px:
                return min(open_, px)
            return None
        if high >= px:
            return max(open_, px)
        return None

    if order.order_type == OrderType.STOP:
        if order.side == OrderSide.BUY:
            if high >= px:
                return max(open_, px)
            return None
        if low <= px:
            return min(open_, px)
        return None

    return open_
